import numpy as np

# Define the function to find a, b, c, d
def find_values():
    for a in np.linspace(1, 10, 1000):
        for b in np.linspace(1, 10, 1000):
            for c in np.linspace(1, 10, 1000):
                for d in np.linspace(1, 10, 1000):
                    if a * b**2 + a * c**2 >= 17 * b * c * d:
                        if (a**2 + b**2 + c**2 + d**2) * (1 / a**2 + 1 / b**2 + 1 / c**2 + 1 / d**2) == 72:
                            return a, b, c, d

# Call the function and print the result
a, b, c, d = find_values()
print(f"{a}, {b}, {c}, {d}")
